import type { ViteDevServer } from "vite";
import type { ClientFunctionWithOptions, ScanConfig } from "./types.d.ts";
import { readdir } from "node:fs/promises";
import { join, resolve } from "node:path";
import process from "node:process";

import { getFunctionsForPrefix } from "./functionsMap.ts";
import { defaultPrefix } from "./options.ts";
import { walkGlobFiles } from "./server-helpers.ts";
import {
  DUPLICATE_FUNCTION_NAME,
  ERROR_LOADING_FILE,
  EXACT_NAMES,
  NO_SERVER_FUNCTION_FOUND,
} from "./constants.ts";

/**
 * Scan targets already performed, so a lazy re-scan is not repeated.
 *
 * Keyed by everything that determines the outcome — the resolved scan root
 * (which files are read), the matching mode, and the prefix prefix-less
 * functions register under. A single process-wide boolean used to be enough
 * only while there was one prefix: the *first* scan suppressed every later
 * one, so a second RPC instance on a different prefix asked for a lazy scan,
 * got an early return, and answered 404 for every function it owned.
 */
const scannedTargets = new Set<string>();

/** Absolute ids (normalized) of the scanned server function files. */
export const scannedServerFiles: Set<string> = new Set<string>();

/**
 * Scans `src/api/` (or an explicit `scanRoot`) for server function files
 * and populates the server functions map (scoped by rpcPrefix) with their exported functions.
 * Uses Vite's SSR module loading to resolve and execute each file.
 *
 * Supports two matching modes via `config.serverFiles`:
 *   `"exact"` — classic `server.ts|js|mjs|mts` names in the api directory
 *   `"glob"` — recursively walking `scanRoot` to match `*.server.{ts,js,mjs,mts}`
 * @param initialCfg - Optional Vite config overrides (root, base, server, serverFiles, scanRoot)
 * @param devServer - Optional running Vite dev server instance; when provided, skips creating a new one
 */
export const scanForServerFiles = async (
  initialCfg?: ScanConfig,
  devServer?: ViteDevServer,
): Promise<void> => {
  // Resolve the scan target up front, before anything expensive. Importing
  // Vite and standing up an internal server are the costly parts, and neither
  // is needed once a scan is known to be a repeat.
  const root = initialCfg?.root || process.cwd();
  const resolvedScanRoot = resolve(
    root,
    initialCfg?.scanRoot ?? join(root, "src", "api"),
  );
  const serverFiles = initialCfg?.serverFiles ?? "exact";
  const target = `${resolvedScanRoot}|${serverFiles}|${
    initialCfg?.rpcPrefix ?? defaultPrefix
  }`;

  if (scannedTargets.has(target) && !devServer) {
    return;
  }
  // Vite is only needed to spin up the internal dev server that loads the
  // server function files, so it is imported lazily rather than at the top
  // of the module. This keeps consumers of the standalone server entry that
  // register their functions directly (e.g. serverless functions bundling
  // the API module) free of a static Vite dependency — when Vite is
  // externalized by the function bundler, this lazy import is left as a
  // runtime require that is never executed.
  let createServer: typeof import("vite").createServer;
  let normalizePath: typeof import("vite").normalizePath;
  try {
    ({ createServer, normalizePath } = await import("vite"));
  } catch {
    // Vite is not installed in this environment (e.g. a serverless bundle
    // where Vite is externalized or absent). Server functions must have been
    // imported directly into the prefix-scoped map; nothing to scan — exit
    // gracefully instead of crashing the host's cold start with
    // `Cannot find module 'vite'`.
    return;
  }
  const config = !initialCfg
    ? {
      root: process.cwd(),
      base: process.env.BASE || "/",
      server: { middlewareMode: true },
    }
    : {
      ...initialCfg,
    };

  let server = devServer;
  if (!server) {
    server = await createServer({
      server: { ...config.server, ws: false },
      appType: "custom",
      base: config.base || "/",
      root: config.root || process.cwd(),
      // The internal server is only used to load the server function files:
      // skip the project config so its plugins (including this one) do not
      // re-trigger a nested scan via `configureServer`.
      configFile: false,
      // The internal server never serves a page or HMR, so no dependency
      // optimization or WebSocket server is needed. Without `ws: false`, the
      // middleware-mode server creates a standalone HMR WebSocket on port
      // 24678, and concurrent scans (e.g. the Express middleware's lazy scan
      // racing the plugin scan) fail with EADDRINUSE. Without `noDiscovery`,
      // the default optimizers scan the project entry and pre-bundle the whole
      // `vite` package (imported by the linked @thednp/rpc dist files),
      // hanging startup at 2+ GB RSS.
      optimizeDeps: { noDiscovery: true },
      ssr: { optimizeDeps: { noDiscovery: true } },
    });
  }

  // Names registered during this scan run, used for duplicate detection.
  // Keyed by `${prefix}:${registeredName}` so the same name can coexist
  // under different rpcPrefixes (see the registration loop below).
  const seenNames = new Set<string>();

  let files: string[];
  try {
    if (serverFiles === "glob") {
      files = await walkGlobFiles(resolvedScanRoot);
    } else {
      files = (await readdir(resolvedScanRoot, { withFileTypes: true }))
        .filter((f) => EXACT_NAMES.includes(f.name))
        .map((f) => join(resolvedScanRoot, f.name));
    }
  } catch (_e) {
    files = [];
  }

  try {
    for (const file of files) {
      scannedServerFiles.add(normalizePath(file));
      let moduleExports: Record<string, ClientFunctionWithOptions>;
      try {
        moduleExports = (await server.ssrLoadModule(file)) as Record<
          string,
          ClientFunctionWithOptions
        >;
      } catch (error) {
        console.error(ERROR_LOADING_FILE, file, error);
        continue;
      }
      const moduleEntries = Object.entries(moduleExports);
      if (!moduleEntries.length) {
        // Warn and move on: returning here would abandon every remaining
        // file in the scan, silently dropping their functions.
        console.warn(NO_SERVER_FUNCTION_FOUND);
        continue;
      }

      // Register each export into its prefix-scoped map, recording the
      // original export name so `getClientModules` can emit the matching
      // client stub. `createServerFunction` already auto-registers its name
      // into the appropriate prefix-scoped map at module load, so a function
      // may already exist here — in that case only the export name is added.
      // Track names seen in THIS scan run only, keyed by prefix: a name
      // repeated within one scan under the same prefix (e.g. two files
      // exporting the same function name) is a genuine conflict.
      for (const [exportName, exportValue] of moduleEntries) {
        const registeredName = exportValue.name;
        const prefix = exportValue.options?.rpcPrefix ||
          config.rpcPrefix ||
          defaultPrefix;
        const seenKey = `${prefix}:${registeredName}`;
        if (seenNames.has(seenKey)) {
          if (process.env.NODE_ENV !== "production") {
            throw new Error(DUPLICATE_FUNCTION_NAME(registeredName));
          }
          console.warn(DUPLICATE_FUNCTION_NAME(registeredName));
          continue;
        }
        seenNames.add(seenKey);
        const prefixMap = getFunctionsForPrefix(prefix);
        const existing = prefixMap.get(registeredName);
        if (existing) {
          existing.exportName = exportName;
        } else {
          prefixMap.set(registeredName, {
            name: registeredName,
            handler: exportValue,
            options: exportValue.options,
            exportName,
          });
        }
      }
    }
  } finally {
    if (!devServer && server) {
      await server.close();
    }
    scannedTargets.add(target);
  }
};
